import { useCallback, useMemo } from 'react';
import { useSelector } from 'react-redux';

import { useCommercialSelectOptions } from 'components/Filter/hooks/useCommercialSelectOptions';
import { FieldProps } from 'components/Filter/types';
import {
  getCommercialDisabledFilterPlaceholder,
  isCommercialFilterFieldEnabled,
} from 'components/Filter/utils/commercialSelectOptions';
import {
  resolveFilterClearTargetOption,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { FilterRegistry } from 'domain/Filter';
import {
  type CommercialSkuDimension,
  type CommercialSkuOption,
  findSubBrandForSku,
  getCommercialSkuOptions,
  shouldAutoLinkSubBrandForSku,
} from 'domain/Filter/commercialResultsSkuHierarchy';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { useGoogleAnalytics, usePageFilterData } from 'hooks';
import { DefaultOptions, FilterForm, Option } from 'models/Filters';
import { filterCommercialResultsPortfolioOptionsForGrowthLever } from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsCrossFilterRules';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';
import { RootState } from 'redux/types';

export const FlatFilterSelectField = ({
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
  dataTestId,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { formDataFilters, defaults } = usePageFilterData(pageName);

  const commercialPresetRefresh = useSelector((state: RootState) =>
    pageName === COMMERCIAL_RESULTS_PAGE_NAME
      ? state.filters.pages[pageName]?.commercialPresetRefresh
      : undefined,
  );

  const isPresetRefreshBlockingField =
    !!commercialPresetRefresh?.pending &&
    (commercialPresetRefresh.skeletonFieldKeys.includes(fieldKey) ?? false);

  const label = useMemo(() => {
    return (
      FilterRegistry.getInstance().get(fieldKey)?.metadata?.displayName ??
      fieldKey
    );
  }, [fieldKey]);

  const appliedSlice = useMemo(
    () => ({
      zone: getCurrentValue('zone'),
      country: getCurrentValue('country'),
      brands: getCurrentValue('brands'),
      sub_brands: getCurrentValue('sub_brands'),
    }),
    [getCurrentValue],
  );

  const accessorRawOptions: Option[] = useMemo(
    () =>
      FilterDataAccessor.getInstance().getOptions(
        fieldKey,
        formDataFilters,
        appliedSlice as FilterForm,
      ) as Option[],
    [fieldKey, formDataFilters, appliedSlice],
  );

  const growthLeverValue = getCurrentValue('growth_levers');
  const constrainedRawOptions = useMemo(
    () =>
      fieldKey === 'portfolios' && pageName === COMMERCIAL_RESULTS_PAGE_NAME
        ? filterCommercialResultsPortfolioOptionsForGrowthLever(
            accessorRawOptions,
            growthLeverValue,
          )
        : accessorRawOptions,
    [accessorRawOptions, fieldKey, growthLeverValue, pageName],
  );

  const formValue = getCurrentValue(fieldKey);
  const defaultValue = defaults[fieldKey];

  const {
    rawOptions,
    selectableOptions,
    isCommercialPage,
    commercialDisplayValue,
  } = useCommercialSelectOptions({
    pageName,
    rawOptions: constrainedRawOptions,
    formValue,
    defaultValue,
  });

  const currentValue = isCommercialPage
    ? commercialDisplayValue
    : (formValue ?? defaultValue ?? '');

  const presetPlaceholder = useMemo(() => {
    if (!isCommercialPage) return undefined;

    const dimension = formDataFilters?.[fieldKey] as DefaultOptions | undefined;
    const defaultLabel = dimension?.default?.label;
    return typeof defaultLabel === 'string' && defaultLabel.length > 0
      ? defaultLabel
      : undefined;
  }, [fieldKey, formDataFilters, isCommercialPage]);

  const fieldEnabled = isCommercialFilterFieldEnabled(
    pageName,
    fieldKey,
    formDataFilters,
  );

  const disabled =
    isPresetRefreshBlockingField ||
    (fieldKey === 'sku' && selectableOptions.length === 0) ||
    !fieldEnabled;

  const optionsForSelect =
    fieldEnabled && !isPresetRefreshBlockingField ? selectableOptions : [];

  const allBrandSkuOptions = useMemo((): CommercialSkuOption[] => {
    if (fieldKey !== 'sku' || !isCommercialPage) {
      return [];
    }
    return getCommercialSkuOptions(
      formDataFilters?.sku as CommercialSkuDimension | undefined,
      appliedSlice.brands,
    );
  }, [fieldKey, isCommercialPage, formDataFilters?.sku, appliedSlice.brands]);

  const handleValueChange = useCallback(
    (option: Option) => {
      if (option?.value === null || option?.value === '') {
        onValueChange(fieldKey, { value: null, label: '' });
        return;
      }
      if (!option?.value) return;
      trackGA({
        event_category: `${label} Select`,
        event_action: 'Select',
        event_label: String(option.value),
      });

      if (fieldKey === 'sku' && isCommercialPage) {
        const linkedSubBrand = findSubBrandForSku(
          allBrandSkuOptions,
          option.value,
        );
        if (
          shouldAutoLinkSubBrandForSku(appliedSlice.sub_brands, linkedSubBrand)
        ) {
          onValueChange('sub_brands', {
            value: linkedSubBrand,
            label: linkedSubBrand,
          });
        }
      }

      onValueChange(fieldKey, option);
    },
    [
      allBrandSkuOptions,
      appliedSlice.sub_brands,
      fieldKey,
      isCommercialPage,
      label,
      onValueChange,
      trackGA,
    ],
  );

  const clearable =
    !disabled &&
    shouldShowFilterSelectClearIndicator(
      pageName,
      fieldKey,
      String(formValue ?? ''),
      rawOptions,
      defaults,
    );

  const handleSelectWrapper = (option: Option | '' | null | undefined) => {
    if (option === '') {
      const target = resolveFilterClearTargetOption(
        fieldKey,
        rawOptions,
        defaults,
      );
      if (target !== undefined) {
        handleValueChange(target);
      }
      return;
    }
    handleValueChange(option as Option);
  };

  const placeholder = (() => {
    if (isPresetRefreshBlockingField) {
      return 'Loading options...';
    }
    if (disabled && fieldKey === 'sku') {
      return 'Select a Brand first';
    }
    if (disabled && !fieldEnabled) {
      return (
        getCommercialDisabledFilterPlaceholder(fieldKey) ??
        'Not available for current selection'
      );
    }
    return presetPlaceholder ?? `Select ${label}`;
  })();

  return (
    <Select
      id={`${fieldKey}-select`}
      label={label}
      value={currentValue}
      options={optionsForSelect}
      disabled={disabled}
      clearable={clearable}
      placeholder={placeholder}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleSelectWrapper(opt as Option | '' | null | undefined);
      }}
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
    />
  );
};
